```java
int[][] g = {{5, 2, 9}, {1, 6, 3}, {8, 4, 7}};
int r = 1, c = 1, greater = 0;
for (int dr = -1; dr <= 1; dr++)
    for (int dc = -1; dc <= 1; dc++) {
        if (dr == 0 && dc == 0) continue;
        int nr = r + dr, nc = c + dc;
        if (nr >= 0 && nr < g.length && nc >= 0 && nc < g[0].length && g[nr][nc] > g[r][c])
            greater++;
    }
System.out.println(greater);
```

